CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id VARCHAR(36) PRIMARY KEY, username VARCHAR(120) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(160) NOT NULL, contact VARCHAR(80), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id VARCHAR(36) NOT NULL, role_id INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS products (id VARCHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, crop_type VARCHAR(100) NOT NULL, description TEXT, image_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classifications (id INT AUTO_INCREMENT PRIMARY KEY, name ENUM('Good','Semi','Reject') NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory (id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(36) NOT NULL, classification_id INT NOT NULL, quantity_kg DECIMAL(12,2) NOT NULL, reserved_kg DECIMAL(12,2) NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY inventory_product_classification_unique (product_id, classification_id), CONSTRAINT fk_inventory_product FOREIGN KEY (product_id) REFERENCES products(id), CONSTRAINT fk_inventory_classification FOREIGN KEY (classification_id) REFERENCES classifications(id));
CREATE TABLE IF NOT EXISTS marketplace_listings (id VARCHAR(36) PRIMARY KEY, inventory_id VARCHAR(36) NOT NULL, price_per_kg DECIMAL(12,2) NOT NULL, status ENUM('draft','published','unavailable','archived') NOT NULL DEFAULT 'draft', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_listings_inventory FOREIGN KEY (inventory_id) REFERENCES inventory(id));
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(36) PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, buyer_id VARCHAR(36) NOT NULL, status ENUM('pending','confirmed','sold','cancelled','rejected') NOT NULL DEFAULT 'pending', contact VARCHAR(80) NOT NULL, pickup_note TEXT NOT NULL, total_amount DECIMAL(12,2) NOT NULL, confirmed_at DATETIME NULL, sold_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_orders_buyer FOREIGN KEY (buyer_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_items (id VARCHAR(36) PRIMARY KEY, order_id VARCHAR(36) NOT NULL, listing_id VARCHAR(36) NOT NULL, quantity_kg DECIMAL(12,2) NOT NULL, price_per_kg DECIMAL(12,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_order_items_order FOREIGN KEY (order_id) REFERENCES orders(id), CONSTRAINT fk_order_items_listing FOREIGN KEY (listing_id) REFERENCES marketplace_listings(id));
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(36) PRIMARY KEY, payment_number VARCHAR(40) NOT NULL UNIQUE, order_id VARCHAR(36) NOT NULL UNIQUE, method ENUM('cash','bank_transfer','manual_reference') NOT NULL, amount DECIMAL(12,2) NOT NULL, recorded_by_id VARCHAR(36) NOT NULL, paid_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES orders(id), CONSTRAINT fk_payments_recorder FOREIGN KEY (recorded_by_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS daily_prices (id VARCHAR(36) PRIMARY KEY, listing_id VARCHAR(36) NOT NULL, price DECIMAL(12,2) NOT NULL, price_date DATE NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, created_by_id VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_daily_prices_listing FOREIGN KEY (listing_id) REFERENCES marketplace_listings(id), CONSTRAINT fk_daily_prices_creator FOREIGN KEY (created_by_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, target VARCHAR(500), read_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_notifications_user FOREIGN KEY (user_id) REFERENCES users(id));
